// ============================================
// LIMPIAR TEXTO DEL PDF ANTES DE PROCESAR
// Combina dos heuristicas (union de ambas versiones del equipo):
// 1) Colapsa encabezados en mayusculas con letras sueltas,
//    ej. "H A B I L I D A D E S" -> "HABILIDADES" (comun cuando
//    el titulo de seccion tiene letter-spacing de diseno).
// 2) Si el problema afecta a TODO el texto, no solo encabezados
//    (tipico de CVs exportados de Canva con letter-spacing global),
//    se reconstruye el texto completo usando el espacio doble como
//    separador real entre palabras.
// ============================================

const textoOriginal = $json.text || '';

function colapsarEncabezados(texto) {
  let limpio = texto.replace(/\b([A-ZÁÉÍÓÚÑ])\s*\n\s*(?=[A-ZÁÉÍÓÚÑ]\b)/g, '$1 ');
  limpio = limpio.replace(/\b(?:[A-ZÁÉÍÓÚÑ]\s+){2,}[A-ZÁÉÍÓÚÑ]\b/g, (m) => m.replace(/\s+/g, ''));
  return limpio;
}

function repararTextoCompleto(texto) {
  const palabras = texto.split(/\s+/).filter(w => w.length > 0);
  const unaLetra = palabras.filter(w => w.length === 1).length;
  const proporcion = palabras.length ? unaLetra / palabras.length : 0;

  if (proporcion <= 0.3) {
    return { texto, reparado: false };
  }

  // El espacio DOBLE es el limite real entre palabras; el espacio
  // SIMPLE se inserto entre cada letra. Se protege el doble espacio
  // con un marcador, se borran los simples, y se restaura el separador.
  const reconstruido = texto.replace(/ {2,}/g, '\u0001').replace(/ /g, '').replace(/\u0001/g, ' ');
  return { texto: reconstruido, reparado: true };
}

const conEncabezadosArreglados = colapsarEncabezados(textoOriginal);
const { texto: textoFinal, reparado } = repararTextoCompleto(conEncabezadosArreglados);

const texto_cv = textoFinal
  .replace(/\r/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 15000);

return [{
  json: {
    ...$json,
    texto_cv,
    longitud_texto: texto_cv.trim().length,
    texto_reparado: reparado,
  },
  binary: $input.first().binary,
}];

