{
  "type": "object",
  "properties": {
    "experiencia_anios": {
      "type": "number",
      "description": "Anios totales de experiencia profesional detectados"
    },
    "habilidades": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Tecnologias y herramientas en minusculas y sin acentos, solo las que aparecen literalmente en el texto"
    },
    "nivel_educativo": {
      "type": "string",
      "enum": ["Bachiller", "Tecnico", "Profesional", "Posgrado", "No definido"],
      "description": "Maximo nivel educativo alcanzado"
    },
    "resumen": {
      "type": "string",
      "description": "Resumen del perfil en maximo 3 frases"
    },
    "preguntas_sugeridas": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Dos o tres preguntas de entrevista basadas en la experiencia declarada"
    }
  },
  "required": ["experiencia_anios", "habilidades", "nivel_educativo", "resumen", "preguntas_sugeridas"]
}

