// ============================================
// CALCULAR EL SCORE DE COMPATIBILIDAD
// Unico nodo Code que decide. La IA ya devolvio JSON
// limpio via Structured Output Parser: aqui solo se
// hace el calculo matematico, el estado y la prioridad.
// Separacion deliberada: la IA EXTRAE, este nodo DECIDE
// con una formula fija y reproducible (no la IA).
// ============================================

const datos = $('Generar Ticket').first().json;
const ia = $input.first().json.output || {};

const VACANTES = {
  'backend-jr':  { requisitos: ['java', 'spring boot', 'sql', 'git', 'rest api'], experiencia_min: 1 },
  'frontend-jr': { requisitos: ['javascript', 'react', 'css', 'html', 'git'],     experiencia_min: 1 },
  'data-jr':     { requisitos: ['sql', 'python', 'power bi', 'excel', 'etl'],     experiencia_min: 1 },
};

const NIVELES_VALIDOS = ['bachiller', 'tecnico', 'tecnologo', 'profesional', 'posgrado'];

function normalizar(txt) {
  return String(txt || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[.,;:()\/\-_]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const vacante = VACANTES[datos.vacante] || { requisitos: [], experiencia_min: 1 };
const requisitos = vacante.requisitos.map(normalizar);

const habilidadesIA = Array.isArray(ia.habilidades) ? ia.habilidades : [];
const habilidades = habilidadesIA.map(normalizar).filter(h => h);

// Coincidencia flexible: "spring boot 3" cuenta como "spring boot"
const coincidencias = requisitos.filter(r =>
  habilidades.some(h => h === r || h.includes(r) || r.includes(h))
);
const faltantes = requisitos.filter(r => !coincidencias.includes(r));

// --- Los tres componentes del score (pesos fijos, no los decide la IA) ---
const total = requisitos.length || 1;
const pHabilidades = (coincidencias.length / total) * 70;

const aniosIA = Number(ia.experiencia_anios);
const anios = (isNaN(aniosIA) || aniosIA < 0) ? (Number(datos.experiencia_declarada) || 0) : aniosIA;
const pExperiencia = Math.min(anios / vacante.experiencia_min, 1) * 20;

const pEducacion = NIVELES_VALIDOS.includes(normalizar(ia.nivel_educativo)) ? 10 : 0;

const score = Math.round(pHabilidades + pExperiencia + pEducacion);

// --- Clasificacion segun rangos del proyecto (unica fuente de verdad) ---
let estado, clasificacion, prioridad_num;
if (score >= 80) {
  estado = 'PRESELECCIONADO'; clasificacion = 'REVISION PRIORITARIA'; prioridad_num = 10;
} else if (score >= 60) {
  estado = 'ANALIZADO'; clasificacion = 'REVISION MANUAL'; prioridad_num = 5;
} else {
  estado = 'PENDIENTE_REVISION'; clasificacion = 'REVISION SECUNDARIA'; prioridad_num = 1;
}

const observaciones = (
  (datos.texto_reparado ? 'Nota: el PDF tenia espaciado entre letras, el texto se reconstruyo automaticamente. ' : '') +
  'Cumple ' + coincidencias.length + ' de ' + total + ' requisitos tecnicos. ' +
  (faltantes.length ? 'Falta: ' + faltantes.join(', ') + '. ' : '') +
  (typeof ia.resumen === 'string' ? ia.resumen : '')
).slice(0, 480);

return [{
  json: {
    ...datos,
    score,
    habilidades_texto: habilidades.join(', '),
    nivel_educativo: ia.nivel_educativo || 'No definido',
    experiencia_final: anios,
    resumen: ia.resumen || '',
    preguntas_sugeridas: Array.isArray(ia.preguntas_sugeridas) ? ia.preguntas_sugeridas.join(' | ') : '',
    observaciones,
    estado,
    clasificacion,
    prioridad_num,
    extraccion_exitosa: true,
    desglose_score: {
      habilidades: Math.round(pHabilidades),
      experiencia: Math.round(pExperiencia),
      educacion: pEducacion,
    },
  },
}];

// ============================================
// PREPARAR DATOS DE LA NOTIFICACION
// Recibe los datos que le manda el flujo 01.
// Normaliza todo para que los nodos siguientes
// no tengan que preocuparse por campos vacios.
// ============================================

const d = $input.first().json;

function limpiar(txt) {
  return String(txt || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// El score puede venir vacio si el PDF no tenia texto
const scoreRaw = d.score;
const tieneScore = !(scoreRaw === null || scoreRaw === undefined || String(scoreRaw).trim() === '');
const score = tieneScore ? Number(scoreRaw) : null;

// Clasificacion segun las reglas del proyecto
let nivel;
if (score === null)      nivel = 'SIN_SCORE';
else if (score >= 80)    nivel = 'ALTA';
else if (score >= 60)    nivel = 'MEDIA';
else                     nivel = 'BAJA';

const etiquetas = {
  ALTA: 'REVISION PRIORITARIA',
  MEDIA: 'REVISION MANUAL',
  BAJA: 'REVISION SECUNDARIA',
  SIN_SCORE: 'REVISION MANUAL - PDF no legible',
};

const id      = limpiar(d.id_candidato || d.id || 'SIN-ID');
const nombre  = limpiar(d.nombre || 'Sin nombre');
const vacante = limpiar(d.vacante || 'No definida');
const correo  = String(d.correo || '').trim();

// Mensaje para el grupo de RRHH (solo si es prioritaria)
const mensajeRRHH =
  '<b>Nueva candidatura analizada</b>\n\n' +
  '<b>ID:</b> ' + id + '\n' +
  '<b>Candidato:</b> ' + nombre + '\n' +
  '<b>Vacante:</b> ' + vacante + '\n' +
  '<b>Compatibilidad:</b> ' + (score === null ? 'sin score' : score + '%') + '\n\n' +
  '<b>Clasificacion:</b> ' + etiquetas[nivel] + '\n\n' +
  'Usa /candidato ' + id + ' para ver el detalle.\n\n' +
  '<i>El score es apoyo para priorizar. La decision es de RRHH.</i>';

// Correo para el candidato: NUNCA incluye score ni evaluacion
const asuntoCandidato = 'Recibimos tu postulacion - ' + id;
const cuerpoCandidato =
  'Hola ' + (d.nombre || '') + ',\n\n' +
  'Recibimos tu postulacion para la vacante ' + (d.vacante || '') + '.\n\n' +
  'Tu numero de radicado es: ' + (d.id_candidato || d.id || '') + '\n\n' +
  'Nuestro equipo de Recursos Humanos revisara tu perfil y te contactara ' +
  'si tu experiencia se ajusta a la oportunidad.\n\n' +
  'Gracias por tu interes.\n\n' +
  'Equipo de Recursos Humanos';

return [{
  json: {
    id_candidato: id,
    nombre,
    vacante,
    correo,
    score,
    nivel,
    es_prioritaria: nivel === 'ALTA',
    tiene_correo: correo.includes('@'),
    mensajeRRHH,
    asuntoCandidato,
    cuerpoCandidato,
  },
}];

// ============================================
// ROUTER DE COMANDOS DEL BOT
// Un solo nodo Code maneja los 4 comandos.
// Siempre devuelve un objeto con la llave "respuesta".
// ============================================

const trigger = $('Telegram Trigger').first().json;

// --- Si no es texto (sticker, foto, audio) ---
if (!trigger.message || !trigger.message.text) {
  return [{ json: { respuesta: 'Solo entiendo mensajes de texto. Escribe /help para ver los comandos.' } }];
}

const mensaje = trigger.message.text.trim();
const partes = mensaje.split(/\s+/);
const comando = partes[0].toLowerCase();
const argumento = partes[1];

// --- Traemos las filas de la hoja ---
const filas = $input.all().map(item => item.json)
  .filter(f => f.ID_Candidato && String(f.ID_Candidato).trim() !== '');

// --- Helpers ---
function limpiar(txt) {
  // Evita que un nombre con < o > rompa el parse_mode HTML de Telegram
  return String(txt || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function scoreNumero(fila) {
  // Las celdas vacias (PDF sin texto) no deben contar como 0
  const v = fila.Score_Compatibilidad;
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}

function textoAyuda() {
  return '<b>Comandos disponibles</b>\n\n' +
    '/candidato TF-2026-0001\n' +
    'Muestra la ficha completa de un candidato.\n\n' +
    '/pendientes\n' +
    'Lista los candidatos que faltan por revisar.\n\n' +
    '/stats\n' +
    'Resumen general del proceso.\n\n' +
    '/help\n' +
    'Muestra este mensaje.';
}

// ============================================
// /help
// ============================================
if (comando === '/help' || comando === '/start') {
  return [{ json: { respuesta: textoAyuda() } }];
}

// ============================================
// /candidato TF-2026-0001
// ============================================
if (comando === '/candidato') {
  if (!argumento) {
    return [{ json: { respuesta: 'Falta el ID del candidato.\nEjemplo: /candidato TF-2026-0001' } }];
  }

  const buscado = argumento.toUpperCase();
  const c = filas.find(f => String(f.ID_Candidato).trim().toUpperCase() === buscado);

  if (!c) {
    return [{ json: { respuesta: 'No encontre el candidato ' + limpiar(argumento) } }];
  }

  const habilidades = String(c.Habilidades || '')
    .split(',')
    .map(h => h.trim())
    .filter(h => h.length > 0)
    .map(h => '- ' + limpiar(h))
    .join('\n') || 'No registradas';

  const s = scoreNumero(c);
  const score = s === null ? 'Pendiente de analisis' : s + '%';

  const respuesta =
    '<b>Candidato:</b> ' + limpiar(c.Nombre || 'Sin nombre') + '\n' +
    '<b>ID:</b> ' + limpiar(c.ID_Candidato) + '\n' +
    '<b>Vacante:</b> ' + limpiar(c.Vacante || 'No definida') + '\n\n' +
    '<b>Compatibilidad:</b> ' + score + '\n' +
    '<b>Experiencia:</b> ' + limpiar(c.Experiencia || '0') + ' anios\n' +
    '<b>Educacion:</b> ' + limpiar(c.Nivel_Educativo || 'No registrada') + '\n\n' +
    '<b>Habilidades:</b>\n' + habilidades + '\n\n' +
    '<b>Estado:</b> ' + limpiar(c.Estado || 'Sin estado') + '\n\n' +
    '<b>Observaciones IA:</b>\n' + limpiar(c.Observaciones_IA || 'Sin observaciones') + '\n\n' +
    '<i>Recuerda: el score es solo apoyo. La decision es de RRHH.</i>';

  return [{ json: { respuesta } }];
}

// ============================================
// /pendientes
// ============================================
if (comando === '/pendientes') {
  const estadosPendientes = ['PENDIENTE_REVISION', 'ANALIZADO', 'RECIBIDO'];

  const pendientes = filas.filter(f =>
    estadosPendientes.includes(String(f.Estado || '').trim().toUpperCase())
  );

  if (pendientes.length === 0) {
    return [{ json: { respuesta: 'No hay candidatos pendientes de revision.' } }];
  }

  // Ordenamos por score de mayor a menor.
  // Los que no tienen score van al final (usamos -1, no 0).
  pendientes.sort((a, b) => {
    const sa = scoreNumero(a);
    const sb = scoreNumero(b);
    return (sb === null ? -1 : sb) - (sa === null ? -1 : sa);
  });

  const lista = pendientes.slice(0, 10).map(c => {
    const s = scoreNumero(c);
    const etiqueta = s === null ? 'sin score' : s + '%';
    return limpiar(c.ID_Candidato) + ' - ' + limpiar(c.Nombre) + ' (' + etiqueta + ')';
  }).join('\n');

  const extra = pendientes.length > 10
    ? '\n\n... y ' + (pendientes.length - 10) + ' mas.'
    : '';

  const respuesta =
    '<b>Pendientes de revision: ' + pendientes.length + '</b>\n' +
    '<i>Ordenados por compatibilidad</i>\n\n' + lista + extra +
    '\n\nUsa /candidato ID para ver el detalle.';

  return [{ json: { respuesta } }];
}

// ============================================
// /stats
// ============================================
if (comando === '/stats') {
  const total = filas.length;

  if (total === 0) {
    return [{ json: { respuesta: 'Todavia no hay postulaciones registradas.' } }];
  }

  // Contar por estado
  const porEstado = {};
  filas.forEach(f => {
    const e = String(f.Estado || 'SIN_ESTADO').trim().toUpperCase();
    porEstado[e] = (porEstado[e] || 0) + 1;
  });

  // Contar por vacante
  const porVacante = {};
  filas.forEach(f => {
    const v = String(f.Vacante || 'sin vacante').trim();
    porVacante[v] = (porVacante[v] || 0) + 1;
  });

  // Promedio de score, ignorando los vacios
  const scores = filas.map(scoreNumero).filter(s => s !== null);
  const promedio = scores.length > 0
    ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
    : 0;

  const altos = scores.filter(s => s >= 80).length;
  const sinScore = total - scores.length;

  const listaEstados = Object.keys(porEstado)
    .map(k => '- ' + k + ': ' + porEstado[k]).join('\n');
  const listaVacantes = Object.keys(porVacante)
    .map(k => '- ' + k + ': ' + porVacante[k]).join('\n');

  const respuesta =
    '<b>Resumen del proceso</b>\n\n' +
    '<b>Total de candidatos:</b> ' + total + '\n' +
    '<b>Score promedio:</b> ' + promedio + '%\n' +
    '<b>Compatibilidad alta (>=80):</b> ' + altos + '\n' +
    '<b>Sin score (revisar manual):</b> ' + sinScore + '\n\n' +
    '<b>Por estado:</b>\n' + listaEstados + '\n\n' +
    '<b>Por vacante:</b>\n' + listaVacantes;

  return [{ json: { respuesta } }];
}

// ============================================
// Comando desconocido
// ============================================
return [{ json: { respuesta: 'No reconozco ese comando.\n\n' + textoAyuda() } }];

// ============================================
// AGREGAR METRICAS PARA EL DASHBOARD
// IMPORTANTE: este nodo es el unico punto donde se decide
// que sale hacia el navegador. A proposito NUNCA se incluyen
// Nombre, Correo ni Telefono: el dashboard es publico-ish
// (protegido solo por la URL del webhook), asi que solo debe
// exponer datos agregados/anonimizados, nunca PII.
// ============================================

const filas = $input.all()
  .map(i => i.json)
  .filter(f => f.ID_Candidato && String(f.ID_Candidato).trim() !== '');

const detalle = filas.map(f => {
  const raw = f.Score_Compatibilidad;
  const sinScore = raw === '' || raw === null || raw === undefined || isNaN(Number(raw));
  return {
    vacante: String(f.Vacante || 'sin_vacante').trim(),
    score: sinScore ? null : Number(raw),
    estado: String(f.Estado || 'SIN_ESTADO').trim().toUpperCase(),
    fecha: String(f.Fecha_Postulacion || '').slice(0, 10) || null,
  };
});

return [{
  json: {
    generado_en: new Date().toISOString(),
    total_candidatos: detalle.length,
    detalle,
    // La hoja solo registra Fecha_Postulacion, no cuando RRHH actualiza
    // Estado o completa Revision_RRHH -> no hay forma de calcular esto
    // sin agregar una columna de fecha de ultima actualizacion.
    tiempo_promedio_revision_dias: null,
    tiempo_promedio_revision_nota: 'No calculable con el esquema actual de la hoja: falta una columna de fecha de ultima actualizacion de Estado/Revision_RRHH.',
  },
}];
